package tests

import (
	"errors"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"exercise/src/rates"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func (c *fakeClock) Now() time.Time {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.now
}

func (c *fakeClock) Advance(d time.Duration) {
	c.mu.Lock()
	c.now = c.now.Add(d)
	c.mu.Unlock()
}

func newClock() *fakeClock { return &fakeClock{now: time.Date(2025, 3, 1, 9, 0, 0, 0, time.UTC)} }

// gatedLoader blocks every call until release is closed, like a slow provider.
type gatedLoader struct {
	calls   atomic.Int32
	release chan struct{}
	fail    atomic.Bool
}

func newGated() *gatedLoader { return &gatedLoader{release: make(chan struct{})} }

func (g *gatedLoader) load(pair string) (rates.Quote, error) {
	g.calls.Add(1)
	<-g.release
	if g.fail.Load() {
		return rates.Quote{}, rates.ErrUnknownPair
	}
	return rates.Quote{Pair: pair, Rate: 1.25}, nil
}

// instant is a loader that never blocks.
func instant(calls *atomic.Int32) rates.Loader {
	return func(pair string) (rates.Quote, error) {
		calls.Add(1)
		return rates.Quote{Pair: pair, Rate: 2}, nil
	}
}

// runConcurrently starts n goroutines, gives them time to pile up behind the
// gate, opens it, and fails the test instead of hanging if they do not finish.
func runConcurrently(t *testing.T, g *gatedLoader, n int, work func(i int)) {
	t.Helper()
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			work(i)
		}(i)
	}
	time.Sleep(150 * time.Millisecond)
	close(g.release)
	done := make(chan struct{})
	go func() { wg.Wait(); close(done) }()
	select {
	case <-done:
	case <-time.After(5 * time.Second):
		t.Fatal("callers still blocked 5s after the provider answered")
	}
}

func TestGetCachesWithinTTL(t *testing.T) {
	var calls atomic.Int32
	cache := rates.NewCache(instant(&calls), time.Minute, newClock())
	for i := 0; i < 3; i++ {
		if _, err := cache.Get("EUR/USD"); err != nil {
			t.Fatal(err)
		}
	}
	if calls.Load() != 1 {
		t.Fatalf("loader called %d times for 3 Gets inside the TTL, want 1", calls.Load())
	}
}

func TestExpiredEntryReloads(t *testing.T) {
	var calls atomic.Int32
	clock := newClock()
	cache := rates.NewCache(instant(&calls), time.Minute, clock)
	cache.Get("EUR/USD")
	clock.Advance(61 * time.Second)
	cache.Get("EUR/USD")
	if calls.Load() != 2 {
		t.Fatalf("loader called %d times, want 2 (reload after the TTL passed)", calls.Load())
	}
}

func TestConcurrentMissesLoadOnce(t *testing.T) {
	g := newGated()
	cache := rates.NewCache(g.load, time.Minute, newClock())
	results := make([]rates.Quote, 40)
	runConcurrently(t, g, 40, func(i int) {
		results[i], _ = cache.Get("EUR/USD")
	})
	t.Logf("provider calls for 40 simultaneous misses: %d", g.calls.Load())
	if g.calls.Load() != 1 {
		t.Fatalf("provider called %d times for one expired key, want 1", g.calls.Load())
	}
	for i, q := range results {
		if q.Rate != 1.25 {
			t.Fatalf("caller %d got rate %v, want 1.25", i, q.Rate)
		}
	}
}

func TestConvertManyLoadsRateOnce(t *testing.T) {
	g := newGated()
	conv := rates.NewConverter(rates.NewCache(g.load, time.Minute, newClock()))
	amounts := make([]int64, 30)
	for i := range amounts {
		amounts[i] = 1000
	}
	var out []int64
	var err error
	runConcurrently(t, g, 1, func(int) { out, err = conv.ConvertMany(amounts, "EUR", "USD") })
	if err != nil {
		t.Fatal(err)
	}
	if len(out) != 30 || out[0] != 1250 || out[29] != 1250 {
		t.Fatalf("unexpected conversion result %v", out)
	}
	if g.calls.Load() != 1 {
		t.Fatalf("provider called %d times converting one invoice, want 1", g.calls.Load())
	}
}

func TestDistinctPairsLoadIndependently(t *testing.T) {
	g := newGated()
	cache := rates.NewCache(g.load, time.Minute, newClock())
	runConcurrently(t, g, 20, func(i int) {
		pair := "EUR/USD"
		if i%2 == 1 {
			pair = "GBP/USD"
		}
		cache.Get(pair)
	})
	if g.calls.Load() != 2 {
		t.Fatalf("provider called %d times for two pairs, want 2", g.calls.Load())
	}
}

func TestFailedLoadIsSharedButNotCached(t *testing.T) {
	g := newGated()
	g.fail.Store(true)
	cache := rates.NewCache(g.load, time.Minute, newClock())
	var failures atomic.Int32
	runConcurrently(t, g, 10, func(int) {
		if _, err := cache.Get("XXX/USD"); errors.Is(err, rates.ErrUnknownPair) {
			failures.Add(1)
		}
	})
	if failures.Load() != 10 {
		t.Fatalf("%d of 10 callers saw the error, want all 10", failures.Load())
	}
	if g.calls.Load() != 1 {
		t.Fatalf("provider called %d times for one failing key, want 1", g.calls.Load())
	}
	g.fail.Store(false)
	if _, err := cache.Get("XXX/USD"); err != nil {
		t.Fatalf("a failed load must not be cached, but the next Get returned %v", err)
	}
	if g.calls.Load() != 2 {
		t.Fatalf("expected a retry after the failure, provider calls = %d", g.calls.Load())
	}
}

func TestInvalidateForcesReload(t *testing.T) {
	var calls atomic.Int32
	cache := rates.NewCache(instant(&calls), time.Minute, newClock())
	cache.Get("EUR/USD")
	cache.Invalidate("EUR/USD")
	cache.Get("EUR/USD")
	if calls.Load() != 2 {
		t.Fatalf("loader called %d times, want 2 after Invalidate", calls.Load())
	}
}
